<?php
/** Pure offline Phase 5 contracts: no provider requests, SMTP or customer data. */
$root=dirname(__DIR__,2);
require $root.'/app/Core/Contracts/KeywordRankingSourceInterface.php';
foreach(['Seo/DataForSeoRankingSource','Seo/DataForSeoClient','GoogleBusiness/LocalRankGridService','GoogleBusiness/NapConsistencyService','Outreach/BacklinkMonitorService','Outreach/DataForSeoLinkGapService','Seo/SeoMonthlyReportService','SeoImpact/SeoImpactService'] as $f)require_once $root.'/app/Services/'.$f.'.php';
$n=0;$fails=0;function check($c,$m){global $n,$fails;$n++;echo($c?'  ok  ':'  FAIL ').$m."\n";if(!$c)$fails++;}function denied($fn){try{$fn();return false;}catch(Throwable $e){return true;}}
$grid=LocalRankGridService::grid(30.0444,31.2357,1);
check(count($grid)===25&&$grid[12]['latitude']===30.0444&&$grid[12]['longitude']===31.2357,'5x5 grid has 25 points centered exactly on the business');
check($grid[0]['latitude']>$grid[12]['latitude']&&$grid[0]['longitude']<$grid[12]['longitude'],'grid row/column ordering matches north-west to south-east heatmap');
check(count(array_unique(array_map(fn($p)=>$p['latitude'].','.$p['longitude'],$grid)))===25,'grid coordinates are unique');
check(denied(fn()=>LocalRankGridService::grid(90,0))&&denied(fn()=>LocalRankGridService::grid(0,181)),'unsupported coordinates rejected');
check(denied(fn()=>LocalRankGridService::grid(30,31,0))&&denied(fn()=>LocalRankGridService::grid(30,31,100)),'grid spacing bounded before paid calls');
check(count(LocalRankGridService::grid(0,0))===25,'zero latitude/longitude are valid coordinates');
check(LocalRankGridService::limits('starter')===['keywords'=>2,'runs'=>1]&&LocalRankGridService::limits('enterprise')['keywords']===3,'plan controls keyword and monthly grid counts');
check(LocalRankGridService::rank([['place_id'=>'branch-a','rank_group'=>4]],['place_id'=>'branch-a'])===4,'Maps rank matches stable place identity');
check(LocalRankGridService::rank([['title'=>'Same business','place_id'=>'branch-b','rank_group'=>1]],['place_id'=>'branch-a'])===null,'same name at another branch is not customer rank');
check(LocalRankGridService::rank([],['place_id'=>'branch-a'])===null,'measured absence is null, not a fabricated zero rank');
check(LocalRankGridService::rank([['cid'=>'123','rank_group'=>7]],['cid'=>'123'])===7,'Maps CID identity supported');
$official=['name'=>'Nile Travel','phone'=>'+20 100 123 4567','website'=>'https://www.nile.example/','address'=>['addressLines'=>['10 Nile St'],'locality'=>'Cairo','regionCode'=>'EG']];
$observed=$official;$observed['name']='NÍLE TRAVEL';$observed['phone']='01001234567';$observed['website']='https://nile.example';
$nap=NapConsistencyService::compare($official,$observed);
check(count(array_filter($nap,fn($x)=>$x['state']==='match'))===4,'NAP normalizes diacritics, local phone prefix and www/trailing slash');
$nap=NapConsistencyService::compare($official,['name'=>'Different Company','phone'=>'+201009999999']);
check($nap['name']['state']==='mismatch'&&$nap['phone']['state']==='mismatch','real name and phone differences create mismatch evidence');
check($nap['address']['state']==='unknown'&&$nap['website']['state']==='unknown','unobserved address/website remain unknown');
check(NapConsistencyService::normalize('website','https://nile.example/branch-a')!==NapConsistencyService::normalize('website','https://nile.example/branch-b'),'different website paths are not treated as equal');
$html='<html><script type="application/ld+json">'.json_encode(['@context'=>'https://schema.org','@graph'=>[['@type'=>'Organization','name'=>'Directory owner','url'=>'https://directory.example'],['@type'=>'TravelAgency','name'=>'Nile Travel','url'=>'https://nile.example','telephone'=>'+201001234567','address'=>['streetAddress'=>'10 Nile St','addressLocality'=>'Cairo','addressCountry'=>'EG']]]]).'</script></html>';
$extracted=NapConsistencyService::extract($html,'nile.example');
check($extracted['name']==='Nile Travel'&&$extracted['phone']==='+201001234567','directory schema selects the customer organization, never the directory brand');
$footer=NapConsistencyService::extract('<footer><a href="tel:+201001234567">Call</a><address>10 Nile St Cairo</address></footer>','nile.example');
check($footer['phone']==='+201001234567'&&$footer['address']==='10 Nile St Cairo','website footer supplies literal phone/address evidence');
$noLink=BacklinkMonitorService::detect('<p>https://nile.example</p><script>"<a href=\"https://nile.example\">fake</a>"</script>','https://source.example/post','nile.example');
check(!$noLink['live'],'plain text mention and scripts are not backlinks');
$link=BacklinkMonitorService::detect('<a href="https://www.nile.example/trips" rel="UGC nofollow sponsored external">Nile <b>tours</b></a>','https://source.example/post','nile.example');
check($link['live']&&$link['anchor']==='Nile tours'&&$link['rel']===['nofollow','sponsored','ugc'],'actual owned anchor records text and rel attributes');
check(!BacklinkMonitorService::detect('<a href="https://nile.example.attacker.test">x</a>','https://source.example','nile.example')['live'],'lookalike target is rejected');
check(BacklinkMonitorService::detect('<a href="//book.nile.example/trip">Book</a>','https://source.example','nile.example')['live'],'owned subdomain and protocol-relative backlink accepted');
check(!BacklinkMonitorService::detect('<a href="/nile.example">fake</a>','https://source.example','nile.example')['live'],'source-relative link does not become a customer backlink');
check(!BacklinkMonitorService::detect('<a href="https://nile.example@attacker.test">fake</a>','https://source.example','nile.example')['live'],'URL credentials cannot disguise backlink host');
$gap=DataForSeoLinkGapService::gap([['domain'=>'already.example']],['one.example'=>[['domain'=>'editor.example'],['domain'=>'already.example'],['domain'=>'single.example']],'two.example'=>[['domain'=>'editor.example'],['domain'=>'editor.example'],['domain'=>'already.example']]]);
check(count($gap)===1&&$gap[0]['domain']==='editor.example'&&count($gap[0]['competitors'])===2,'link gap requires two distinct competitors and excludes customer referring domains');
check(DataForSeoLinkGapService::gap([],['one.example'=>[['domain'=>'same.example'],['domain'=>'same.example']]])===[],'duplicate links from one competitor do not invent a multi-competitor gap');
check($gap[0]['source']==='dataforseo_backlinks'&&!isset($gap[0]['email']),'outreach prospects retain real provider provenance without invented contact details');
$settings=['enabled'=>'1','login'=>'fixture','password'=>'offline','monthly_budget_usd'=>10];$calls=0;
$client=new DataForSeoClient($settings,function()use(&$calls){$calls++;});
check(!$client->call('serp/google/maps/live/advanced',[[]],1,1,.1)['available']&&$calls===0,'Maps admin switch stops before billing/transport');
check(!$client->call('backlinks/referring_domains/live',[[]],1,1,1)['available']&&$calls===0,'Backlinks admin switch stops before billing/transport');
check(SeoMonthlyReportService::month('2026-03-15')===['start'=>'2026-02-01','end'=>'2026-02-28'],'report uses the previous complete calendar month');
check(SeoMonthlyReportService::month('2024-03-01')['end']==='2024-02-29','monthly period handles leap years');
$data=SeoMonthlyReportService::assemble(['gsc'=>['state'=>'measured','clicks'=>0,'impressions'=>0,'top_queries'=>[]],'rankings'=>[['label'=>'Egypt','keyword'=>'Luxor','position'=>null,'checked_at'=>'2026-09-30']],'tasks'=>[['title'=>'<script>x</script>','status'=>'verified']],'impact'=>[['page_url'=>'https://nile.example/trip','window_days'=>7,'status'=>'waiting_period','result'=>null]]],['start'=>'2026-09-01','end'=>'2026-09-30']);
check($data['gsc']['clicks']===0&&$data['core_web_vitals']===null,'report preserves measured zero vs unknown source');
$report=SeoMonthlyReportService::html($data,'https://nile.example');
check(str_contains($report,'dir="rtl"')&&str_contains($report,'@media print'),'monthly Arabic HTML supports print/PDF layout');
check(!str_contains($report,'<script>')&&str_contains($report,'&lt;script&gt;'),'report escapes task/source text');
check(str_contains($report,'غير مقاس')&&str_contains($report,'ليست إثباتًا'),'waiting impact is not fabricated measurement or causal proof');
check(isset($data['next_plan'],$data['rankings'],$data['ai_visibility'],$data['tasks'],$data['impact']),'report assembly includes all requested metric and planning sections');
$windows=SeoImpactService::automaticWindows('2026-10-17','2026-10-17');
check(array_column($windows,'window_days')===[7,14,28],'automatic monitoring creates all three observation windows');
check($windows[0]['due_at']==='2026-10-27 04:00:00'&&$windows[2]['due_at']==='2026-11-17 04:00:00','automatic monitoring respects complete-window and GSC lag dates');
$map=require $root.'/app/Config/project_classmap.php';check(isset($map['LocalRankGridService'],$map['NapConsistencyService'],$map['SeoMonthlyReportService']),'new services registered for hosting without composer rebuild');
$settingsSource=file_get_contents($root.'/app/Controllers/AdminController.php');check(str_contains($settingsSource,'ss_serp_local_enabled')&&str_contains($settingsSource,'ss_serp_backlinks_enabled'),'independent paid-provider admin switches have real inputs');
$cron=file_get_contents($root.'/cron/schedule.php');check(str_contains($cron,"'gbp_background_sync'")&&str_contains($cron,"'seo_auto_impact'"),'GBP scheduling and monitor backfill registered centrally');
echo "\n".($n-$fails)."/$n passed\n";exit($fails?1:0);
